// Layout primitive (Category B) — arrangement only, owns no look.
// Carve-out 5 (component-contract.md §6): references Sys layout scales directly,
// has no Cmp token layer. 1D flow (row/column) with token-scale gap. Responsive:
// every layout prop accepts `T | { small, medium, large }` (see block-contract.md § Responsive).
import type { CSSProperties, ElementType, HTMLAttributes, Ref } from "react";
import { responsiveVars, type Responsive } from "./responsive";
import "./Stack.css";

type Gap =
  | "none"
  | "2x-small"
  | "x-small"
  | "small"
  | "medium"
  | "large"
  | "x-large"
  | "2x-large";
type Direction = "row" | "column";
type Align = "start" | "center" | "end" | "stretch" | "baseline";
type Justify = "start" | "center" | "end" | "between" | "around";

const gapValue = (v: Gap) => (v === "none" ? "0" : `var(--sd-space-${v})`);
const alignValue = (v: Align) => (v === "start" ? "flex-start" : v === "end" ? "flex-end" : v);
const justifyValue = (v: Justify) =>
  v === "start"
    ? "flex-start"
    : v === "end"
      ? "flex-end"
      : v === "between"
        ? "space-between"
        : v === "around"
          ? "space-around"
          : v;

export interface StackProps extends Omit<HTMLAttributes<HTMLElement>, "className"> {
  /**
   * Flow axis. A responsive value's default is the value at every rung.
   *
   * @default "column"
   */
  direction?: Responsive<Direction>;
  /**
   * Space between children, from the Sys space scale.
   *
   * @default "medium"
   */
  gap?: Responsive<Gap>;
  /**
   * Cross-axis alignment (align-items). Defaults to stretch. `baseline` lines up the first text
   * baselines of a row whose children set different type sizes, such as a key beside its value.
   */
  align?: Responsive<Align>;
  /** Main-axis distribution (justify-content). Defaults to start. */
  justify?: Responsive<Justify>;
  /** Allow children to wrap onto multiple lines. */
  wrap?: boolean;
  /**
   * As a child of a row or column, take an equal share of the room its siblings leave on that
   * axis, as a design tool's Fill does for a frame. A control fills through its own `isFullWidth`.
   */
  grow?: boolean;
  /** Render as a different element (e.g. "nav", "ul", "section"). */
  as?: ElementType;
  className?: string;
  style?: CSSProperties;
  ref?: Ref<HTMLElement>;
}

export function Stack({
  direction = "column",
  gap = "medium",
  align,
  justify,
  wrap,
  grow,
  as: Component = "div",
  className,
  style,
  ...props
}: StackProps) {
  return (
    <Component
      {...props}
      data-wrap={wrap || undefined}
      data-grow={grow || undefined}
      className={className ? `sd-stack ${className}` : "sd-stack"}
      style={{
        ...responsiveVars("direction", direction, (v) => v),
        ...responsiveVars("gap", gap, gapValue),
        ...responsiveVars("align", align, alignValue),
        ...responsiveVars("justify", justify, justifyValue),
        ...style,
      }}
    />
  );
}

/* Stack.css — .sd-stack
   Layout primitive: arrangement only. Carve-out 5 — references Sys space scale
   directly (no Cmp layer). Responsive props arrive as --sd-layout-* local custom
   properties (set inline by the component); the CSS applies them mobile-first with
   a base → md (768px) fallback cascade. --sd-layout-* are local intermediates, not
   tokens. Single class, no descendant combinators. */
.sd-stack {
  /* Block inheritance: --sd-layout-* are set inline per instance. Without this reset a
     nested Stack would inherit an ancestor's responsive (-md) value and flip its axis. */
  --sd-layout-direction-small: initial;
  --sd-layout-direction-medium: initial;
  --sd-layout-direction-large: initial;
  --sd-layout-gap-small: initial;
  --sd-layout-gap-medium: initial;
  --sd-layout-gap-large: initial;
  --sd-layout-align-small: initial;
  --sd-layout-align-medium: initial;
  --sd-layout-align-large: initial;
  --sd-layout-justify-small: initial;
  --sd-layout-justify-medium: initial;
  --sd-layout-justify-large: initial;
  display: flex;
  flex-direction: var(--sd-layout-direction-small, column);
  gap: var(--sd-layout-gap-small, var(--sd-space-medium));
  align-items: var(--sd-layout-align-small, stretch);
  justify-content: var(--sd-layout-justify-small, flex-start);
}

@media (min-width: 768px) {
  .sd-stack {
    flex-direction: var(--sd-layout-direction-medium, var(--sd-layout-direction-small, column));
    gap: var(--sd-layout-gap-medium, var(--sd-layout-gap-small, var(--sd-space-medium)));
    align-items: var(--sd-layout-align-medium, var(--sd-layout-align-small, stretch));
    justify-content: var(
      --sd-layout-justify-medium,
      var(--sd-layout-justify-small, flex-start)
    );
  }
}

@media (min-width: 1024px) {
  .sd-stack {
    flex-direction: var(
      --sd-layout-direction-large,
      var(--sd-layout-direction-medium, var(--sd-layout-direction-small, column))
    );
    gap: var(
      --sd-layout-gap-large,
      var(--sd-layout-gap-medium, var(--sd-layout-gap-small, var(--sd-space-medium)))
    );
    align-items: var(
      --sd-layout-align-large,
      var(--sd-layout-align-medium, var(--sd-layout-align-small, stretch))
    );
    justify-content: var(
      --sd-layout-justify-large,
      var(--sd-layout-justify-medium, var(--sd-layout-justify-small, flex-start))
    );
  }
}

.sd-stack[data-wrap] {
  flex-wrap: wrap;
}

/* Fill, as a child of a row or column: an equal share of what the siblings leave (a zero basis),
   allowed to shrink across the inline axis past its content. The block minimum stays automatic,
   since a column of unknown height would otherwise collapse a growing Stack to nothing. */
.sd-stack[data-grow] {
  flex: 1 1 0%;
  min-inline-size: 0;
}
